package com.aditya.search.repo; import com.aditya.search.model.Document; import org.springframework.data.jpa.repository.*; import java.util.*; public interface DocumentRepository extends JpaRepository<Document,Long> { @Query("select d from Document d where lower(d.title) like lower(concat('%', :q, '%')) or lower(d.content) like lower(concat('%', :q, '%'))") List<Document> search(String q); }
